1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the debouncer module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- VUnit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	
14	library vunit_lib;
15	context vunit_lib.vunit_context;
16	
17	library osvvm;
18	use osvvm.RandomPkg.RandomPType;
19	
20	use work.tb_utils.all;
21	use work.utils_pkg.all;
22	
23	
24	entity tb_debouncer is
25	    generic (
26	        runner_cfg: string := runner_cfg_default;
27	        tb_path: string
28	    );
29	end entity;
30	
31	architecture tb of tb_debouncer is
32	    -------------------------------------------------------------
33	    -- Internal tb signals/constants
34	    -------------------------------------------------------------
35	    constant PROPAGATION_TIME: time := 1 ns;
36	    constant SIMULATION_TIMEOUT_TIME: time := 10 ms;
37	    constant ENABLE_DEBUG_PRINT: boolean := false;
38	
39	    signal clk_enable: std_ulogic := '1';
40	    signal simulation_done: boolean := false;
41	    -------------------------------------------------------------
42	
43	    -------------------------------------------------------------
44	    -- DuT signals, constants
45	    -------------------------------------------------------------
46	    constant CLK_FREQUENCY: real := real(100e6); -- 100 MHz
47	    constant DEBOUNCE_SYNC_BITS: natural := 4; -- Small value for simulation time
48	    constant POLARITY: std_ulogic := '1';
49	
50	    signal clk: std_ulogic := '0';
51	    signal input: std_ulogic := not POLARITY;
52	    signal output: std_ulogic;
53	    ------------------------------------------------------------
54	begin
55	    ------------------------------------------------------------
56	    -- CLOCK Generation
57	    ------------------------------------------------------------
58	    generate_advanced_clock(clk, CLK_FREQUENCY, 0 fs, clk_enable);
59	    ------------------------------------------------------------
60	
61	    ------------------------------------------------------------
62	    -- VUnit
63	    ------------------------------------------------------------
64	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
65	
66	    main: process
67	    begin
68	        test_runner_setup(runner, runner_cfg);
69	        info("Starting tb_debouncer");
70	
71	        if ENABLE_DEBUG_PRINT then
72	            show(display_handler, debug);
73	        end if;
74	
75	        wait until simulation_done;
76	        info("Debouncer tests completed successfully!" & LF);
77	
78	        test_runner_cleanup(runner);
79	        wait;
80	    end process;
81	    ------------------------------------------------------------
82	
83	    ------------------------------------------------------------
84	    -- Checker
85	    ------------------------------------------------------------
86	    checker: process
87	        constant DEBOUNCE_WAIT_CYCLES: natural := 2**DEBOUNCE_SYNC_BITS + 2; -- Allow for debounce time plus some margin
88	
89	        variable random: RandomPType;
90	
91	        procedure wait_clk_cycles(cycles: natural) is begin
92	            for i in 0 to cycles - 1 loop
93	                wait until rising_edge(clk);
94	            end loop;
95	            wait for PROPAGATION_TIME;
96	        end procedure;
97	
98	        procedure test_initial_state is begin
99	            info("1.0) Testing initial state");
100	
101	            -- Check that output starts at not POLARITY
102	            check_equal(output, not POLARITY, "Initial output should be not POLARITY");
103	
104	            info("Initial state test passed" & LF);
105	        end procedure;
106	
107	        procedure test_clean_transition is begin
108	            info("2.0) Testing clean transition");
109	
110	            input <= POLARITY;
111	
112	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
113	            check_equal(output, POLARITY, "Output should change after stable input");
114	
115	            input <= not POLARITY;
116	
117	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
118	            check_equal(output, not POLARITY, "Output should change back after stable input");
119	
120	            info("Clean transition test passed" & LF);
121	        end procedure;
122	
123	        procedure test_bouncy_transition is begin
124	            info("3.0) Testing bouncy transition");
125	
126	            -- Start with input at not POLARITY
127	            input <= not POLARITY;
128	            wait_clk_cycles(5);
129	
130	            -- Simulate bouncy transition with multiple changes
131	            input <= POLARITY;
132	            wait_clk_cycles(1);
133	            input <= not POLARITY;
134	            wait_clk_cycles(1);
135	            input <= POLARITY;
136	            wait_clk_cycles(1);
137	            input <= not POLARITY;
138	            wait_clk_cycles(1);
139	            input <= POLARITY; -- Final stable state
140	
141	            check_equal(output, not POLARITY, "Output should not change during bouncy transition");
142	
143	            wait_clk_cycles(2**DEBOUNCE_SYNC_BITS - 2);
144	            check_equal(output, not POLARITY, "Output should not change before debounce time");
145	
146	            wait_clk_cycles(4);
147	            check_equal(output, POLARITY, "Output should change after debounce time");
148	
149	            info("Bouncy transition test passed" & LF);
150	        end procedure;
151	
152	        procedure test_partial_debounce is begin
153	            info("4.0) Testing partial debounce reset");
154	
155	            input <= POLARITY;
156	            wait_clk_cycles(5);
157	
158	            input <= not POLARITY;
159	
160	            wait_clk_cycles(2**DEBOUNCE_SYNC_BITS - 1);
161	            input <= POLARITY;
162	
163	            check_equal(output, POLARITY, "Output should not change when transition interrupted");
164	
165	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
166	            check_equal(output, POLARITY, "Output should remain stable when bounce returns to original state");
167	
168	            info("Partial debounce test passed" & LF);
169	        end procedure;
170	
171	        procedure test_rapid_transitions is begin
172	            info("5.0) Testing rapid transitions");
173	
174	            -- Start with input at POLARITY
175	            input <= POLARITY;
176	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
177	
178	            check_equal(output, POLARITY, "Starting state should be POLARITY");
179	
180	            for i in 0 to 9 loop
181	                input <= not input;
182	                wait_clk_cycles(1);
183	            end loop;
184	
185	            input <= not POLARITY;
186	
187	            check_equal(output, POLARITY, "Output should not change during rapid transitions");
188	
189	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
190	            check_equal(output, not POLARITY, "Output should change after input stabilizes");
191	
192	            info("Rapid transitions test passed" & LF);
193	        end procedure;
194	
195	        procedure test_random_debouncer is
196	            variable bounce_amount: natural;
197	            variable random_repetitions: natural;
198	            variable random_input: std_ulogic;
199	            variable expected_output: std_ulogic;
200	        begin
201	            info("6.x) test_random_debouncer");
202	
203	            bounce_amount := random.RandInt(10, 100);
204	            random_repetitions := random.RandInt(2, 5);
205	
206	            info("6.1) test_random_debouncer");
207	            input <= '0';
208	            wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
209	            check_equal(output, '0', "output should be '0' when input is '0'");
210	
211	            for j in 0 to random_repetitions - 1 loop
212	                info("6." & to_string(j) & "1" & ") test_random_debouncer");
213	                expected_output := output;
214	
215	                for i in 0 to bounce_amount - 1 loop
216	                    input <= random.RandSlv(1)(1);
217	                    check_equal(output, expected_output, "output should be " & to_string(not POLARITY) & " when input is '0'");
218	                    wait_clk_cycles(1);
219	                    input <= random.RandSlv(1)(1);
220	                    check_equal(output, expected_output, "output should be " & to_string(not POLARITY) & " when input is '1'");
221	                    wait_clk_cycles(1);
222	                end loop;
223	
224	                info("6." & to_string(j) & "2" & ") test_random_debouncer");
225	                random_input := random.RandSlv(1)(1);
226	                input <= random_input;
227	                wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
228	                check_equal(output, input, "output should be " & to_string(input) & " when input is " & to_string(input));
229	
230	                info("6." & to_string(j) & "2" & ") test_random_debouncer");
231	                for i in 0 to bounce_amount - 1 loop
232	                    input <= random.RandSlv(1)(1);
233	                    check_equal(output, random_input, "output should be " & to_string(input) & " when input is " & to_string(input));
234	                    wait_clk_cycles(1);
235	                    input <= random.RandSlv(1)(1);
236	                    check_equal(output, random_input, "output should be " & to_string(input) & " when input is " & to_string(input));
237	                    wait_clk_cycles(1);
238	                end loop;
239	
240	                info("6." & to_string(j) & "2" & ") test_random_debouncer");
241	                input <= not random_input;
242	                wait_clk_cycles(DEBOUNCE_WAIT_CYCLES);
243	                check_equal(output, input, "output should be '0' when input is '0'");
244	            end loop;
245	
246	            info("Random debouncer test passed" & LF);
247	        end procedure;
248	    begin
249	        random.InitSeed(tb_path & random'instance_name);
250	
251	        -- Don't remove, else VUnit will not run the test suite
252	        wait_clk_cycles(1);
253	
254	        while test_suite loop
255	            if run("test_initial_state") then
256	                test_initial_state;
257	            elsif run("test_clean_transition") then
258	                test_clean_transition;
259	            elsif run("test_bouncy_transition") then
260	                test_bouncy_transition;
261	            elsif run("test_partial_debounce") then
262	                test_partial_debounce;
263	            elsif run("test_rapid_transitions") then
264	                test_rapid_transitions;
265	            elsif run("test_random_debouncer") then
266	                test_random_debouncer;
267	            else
268	                assert false report "No test has been run!" severity failure;
269	            end if;
270	        end loop;
271	
272	        simulation_done <= true;
